from pathlib import Path
p = Path(r'C:\Users\user\Desktop\the\index.html')
s = p.read_text(encoding='utf-8')

s = s.replace('<button class="user" aria-label="Cart">', '<button class="sound-toggle" id="sound-toggle" aria-label="Toggle sound" aria-pressed="false">Sound</button><button class="user" id="cart-open" aria-label="Cart">', 1)

css = r'''
.sound-toggle{margin-left:auto;margin-right:12px;padding:8px 12px;border:1px solid rgba(255,255,255,.22);border-radius:999px;font-size:11px;opacity:.8;transition:background .2s,opacity .2s}.sound-toggle:hover,.sound-toggle.is-on{background:rgba(255,255,255,.2);opacity:1}.panel__card--wide{width:min(720px,100%);max-height:min(82vh,720px);overflow:auto}.panel__products{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:20px}.panel__product{padding:12px;border-radius:16px;background:rgba(255,255,255,.1);text-align:left}.panel__product-art{height:100px;border-radius:12px;overflow:hidden;background:rgba(0,0,0,.14);margin-bottom:10px}.panel__product-art svg{height:135%;width:100%;transform:translateY(-7%)}.panel__product h3{font-size:13px;font-weight:500}.panel__product p{margin-top:5px;font-size:11px;line-height:1.45}.panel__product button{margin-top:10px;padding:8px 10px;border-radius:999px;background:var(--white);color:var(--ink);font-size:11px}.form{display:grid;gap:10px;margin-top:18px}.form label{font-size:11px;opacity:.75}.form input,.form textarea{width:100%;padding:11px 12px;border:1px solid rgba(255,255,255,.22);border-radius:10px;background:rgba(0,0,0,.14);color:var(--white);font:inherit;font-size:13px;outline:none}.form textarea{min-height:92px;resize:vertical}.form input:focus,.form textarea:focus{border-color:var(--white);box-shadow:0 0 0 3px rgba(255,255,255,.12)}.form button,.share-btn{justify-self:start;padding:10px 16px;border-radius:999px;background:var(--white);color:var(--ink);font-size:12px;font-weight:600}.form__status{font-size:12px;color:var(--white);min-height:18px}.share-row{display:flex;gap:8px;flex-wrap:wrap;margin-top:18px}.share-btn{background:rgba(255,255,255,.14);color:var(--white);font-weight:500}.share-btn:hover{background:rgba(255,255,255,.25)}.cart-drawer{position:absolute;inset:0;z-index:45;pointer-events:none;visibility:hidden;background:rgba(17,9,4,.3);transition:visibility .3s,background .3s}.cart-drawer.is-open{pointer-events:auto;visibility:visible;background:rgba(17,9,4,.5)}.cart-drawer__card{position:absolute;top:0;right:0;width:min(420px,100%);height:100%;padding:32px var(--gutter);background:linear-gradient(160deg,#4c2a18,#211109);box-shadow:-20px 0 60px rgba(0,0,0,.28);transform:translateX(100%);transition:transform .4s cubic-bezier(.2,.8,.2,1);overflow:auto}.cart-drawer.is-open .cart-drawer__card{transform:translateX(0)}.cart-drawer__head{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.18);padding-bottom:18px}.cart-drawer__head h2{font-family:Anton,sans-serif;font-size:34px;font-weight:400;text-transform:uppercase}.cart-drawer__close{width:32px;height:32px;border-radius:50%;background:rgba(255,255,255,.13);font-size:20px}.cart-item{display:grid;grid-template-columns:58px 1fr auto;gap:12px;align-items:center;padding:16px 0;border-bottom:1px solid rgba(255,255,255,.12)}.cart-item__art{width:58px;height:68px;border-radius:10px;overflow:hidden;background:rgba(255,255,255,.1)}.cart-item__art svg{width:100%;height:125%;transform:translateY(-8%)}.cart-item h3{font-size:13px;font-weight:500}.cart-item p{margin-top:5px;font-size:11px;opacity:.7}.cart-item__qty{display:flex;align-items:center;gap:7px;margin-top:8px;font-size:12px}.cart-item__qty button{width:20px;height:20px;border-radius:5px;background:rgba(255,255,255,.14)}.cart-item__price{font-size:13px}.cart-empty{padding:30px 0;font-size:13px;color:var(--muted)}.cart-total{display:flex;justify-content:space-between;margin-top:24px;font-size:15px;font-weight:600}.cart-checkout{width:100%;margin-top:18px;padding:13px;border-radius:999px;background:var(--white);color:var(--ink);font-size:13px;font-weight:600}.mobile-cart{display:none}
@media(max-width:760px){.sound-toggle{margin-right:8px;padding:7px 9px}.panel__products{grid-template-columns:1fr}.panel__card--wide{max-height:78vh}.mobile-cart{position:absolute;display:block;z-index:15;left:16px;right:16px;bottom:14px;padding:12px;border-radius:999px;background:var(--white);color:var(--ink);font-size:12px;font-weight:600;box-shadow:0 10px 25px rgba(0,0,0,.2);pointer-events:auto}.info .btn{margin-bottom:42px}}
'''
s = s.replace('</style>', css + '</style>', 1)

markup = '<div class="cart-drawer" id="cart-drawer" role="dialog" aria-modal="true" aria-labelledby="cart-title" aria-hidden="true"><aside class="cart-drawer__card"><div class="cart-drawer__head"><h2 id="cart-title">Your cart</h2><button class="cart-drawer__close" id="cart-close" aria-label="Close cart">×</button></div><div id="cart-items"></div><div class="cart-total"><span>Total</span><strong id="cart-total">$0.00</strong></div><button class="cart-checkout" id="checkout">Checkout</button></aside></div><button class="mobile-cart" id="mobile-cart">View cart · <span id="mobile-cart-count">0</span></button>'
s = s.replace('</main>', markup + '</main>', 1)

s = s.replace("let index=0,qty=1,cart=0,busy=false,current=null;", "let index=0,qty=1,cart=0,busy=false,current=null,cartItems=[],soundOn=false;")

fallback = "if(!window.gsap){window.gsap={timeline:()=>{const t={from(){return t},to(){return t}};return t},fromTo:(el,a,b)=>{if(b&&b.onComplete)b.onComplete()}};}"
s = s.replace("const $=s=>document.querySelector(s),stage=", fallback + "const $=s=>document.querySelector(s),stage=", 1)

s = s.replace("openPanel(label)", "openEnhancedPanel(label)")

extra = r'''
function openEnhancedPanel(type){const c=panelContent[type];panel.classList.toggle('panel__wide',type==='Shop');panelEyebrow.textContent=c.eyebrow;panelTitle.textContent=c.title;const p=type==='Shop'?`<p>${c.body}</p><div class="panel__products">${PRODUCTS.map((x,i)=>`<article class="panel__product"><div class="panel__product-art" style="background:radial-gradient(circle at 50% 40%,${x.bg[0]},${x.bg[1]})">${canSVG(x.can,{mini:true})}</div><h3>${x.name.join(' ')}</h3><p>${x.sub} · ${money(x.price)}</p><button data-detail="${i}">View details</button></article>`).join('')}</div>`:type==='Contact'?`<p>${c.body}</p><form class="form" id="contact-form"><label for="contact-name">Name</label><input id="contact-name" required placeholder="Your name"><label for="contact-email">Email</label><input id="contact-email" type="email" required placeholder="you@example.com"><label for="contact-message">Message</label><textarea id="contact-message" required placeholder="How can we help?"></textarea><button type="submit">Send message</button><div class="form__status" id="contact-status" role="status"></div></form>`:`<p>${c.body}</p><div class="share-row"><button class="share-btn" id="share-page">Share Velvetspoon</button><button class="share-btn" id="copy-page">Copy link</button></div><form class="form" id="newsletter-form"><label for="newsletter-email">Join the spoon club</label><input id="newsletter-email" type="email" required placeholder="Email address"><button type="submit">Subscribe</button><div class="form__status" id="newsletter-status" role="status"></div></form>`;panelBody.innerHTML=p;panel.classList.add('is-open');panel.setAttribute('aria-hidden','false');panelClose.focus();panelBody.querySelectorAll('[data-detail]').forEach(b=>b.addEventListener('click',()=>showProductDetail(Number(b.dataset.detail))));const form=$('#contact-form');if(form)form.addEventListener('submit',e=>{e.preventDefault();$('#contact-status').textContent='Thanks — your message is ready to be received.';form.reset()});const nf=$('#newsletter-form');if(nf)nf.addEventListener('submit',e=>{e.preventDefault();$('#newsletter-status').textContent='You are on the list. Welcome to the spoon club.';nf.reset()});const share=$('#share-page');if(share)share.addEventListener('click',async()=>{if(navigator.share)await navigator.share({title:'Velvetspoon — Desserts in a Can',text:'Discover Velvetspoon desserts in a can.',url:location.href});else $('#newsletter-status').textContent='Use Copy link to share Velvetspoon.'});const copy=$('#copy-page');if(copy)copy.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(location.href);$('#newsletter-status').textContent='Link copied.'}catch{$('#newsletter-status').textContent='Copy the page URL from your browser.'}})}
function showProductDetail(i){const p=PRODUCTS[i];panelEyebrow.textContent=p.sub;panelTitle.textContent=p.name.join(' ');panelBody.innerHTML=`<p>${p.desc}</p><p><strong>Serving:</strong> 180g chilled dessert. Keep refrigerated and enjoy straight from the can.</p><div class="share-row"><button class="share-btn" id="detail-add">Add to cart · ${money(p.price)}</button><button class="share-btn" id="detail-back">Back to flavours</button></div>`;$('#detail-add').addEventListener('click',()=>{addToCart(i,1);closePanel();openCart()});$('#detail-back').addEventListener('click',()=>openEnhancedPanel('Shop'))}
function addToCart(i,n){const item=cartItems.find(x=>x.i===i);if(item)item.qty+=n;else cartItems.push({i,qty:n});cart=cartItems.reduce((a,x)=>a+x.qty,0);badge.textContent=cart;badge.classList.toggle('is-on',cart>0);renderCart()}
function renderCart(){const wrap=$('#cart-items'),mobile=$('#mobile-cart-count');mobile.textContent=cart;wrap.innerHTML=cartItems.length?cartItems.map((x,k)=>{const p=PRODUCTS[x.i];return `<div class="cart-item"><div class="cart-item__art" style="background:radial-gradient(circle at 50% 40%,${p.bg[0]},${p.bg[1]})">${canSVG(p.can,{mini:true})}</div><div><h3>${p.name.join(' ')}</h3><p>${money(p.price)} each</p><div class="cart-item__qty"><button data-cart-minus="${k}" aria-label="Decrease ${p.name.join(' ')}">−</button><span>${x.qty}</span><button data-cart-plus="${k}" aria-label="Increase ${p.name.join(' ')}">+</button><button data-cart-remove="${k}" aria-label="Remove ${p.name.join(' ')}">Remove</button></div></div><div class="cart-item__price">${money(p.price*x.qty)}</div></div>`}).join(''):'<p class="cart-empty">Your cart is waiting for something delicious.</p>';const total=cartItems.reduce((a,x)=>a+PRODUCTS[x.i].price*x.qty,0);$('#cart-total').textContent=money(total);wrap.querySelectorAll('[data-cart-minus]').forEach(b=>b.addEventListener('click',()=>updateCart(Number(b.dataset.cartMinus),-1)));wrap.querySelectorAll('[data-cart-plus]').forEach(b=>b.addEventListener('click',()=>updateCart(Number(b.dataset.cartPlus),1)));wrap.querySelectorAll('[data-cart-remove]').forEach(b=>b.addEventListener('click',()=>{cartItems.splice(Number(b.dataset.cartRemove),1);syncCart()}))}
function updateCart(k,d){cartItems[k].qty=Math.max(0,Math.min(20,cartItems[k].qty+d));if(!cartItems[k].qty)cartItems.splice(k,1);syncCart()}function syncCart(){cart=cartItems.reduce((a,x)=>a+x.qty,0);badge.textContent=cart;badge.classList.toggle('is-on',cart>0);renderCart()}function openCart(){$('#cart-drawer').classList.add('is-open');$('#cart-drawer').setAttribute('aria-hidden','false');$('#cart-close').focus()}function closeCart(){$('#cart-drawer').classList.remove('is-open');$('#cart-drawer').setAttribute('aria-hidden','true')}
$('#shop').addEventListener('click',()=>addToCart(index,qty));$('#cart-open').addEventListener('click',openCart);$('#mobile-cart').addEventListener('click',openCart);$('#cart-close').addEventListener('click',closeCart);$('#cart-drawer').addEventListener('click',e=>{if(e.target.id==='cart-drawer')closeCart()});$('#checkout').addEventListener('click',()=>{if(!cartItems.length){$('#cart-items').innerHTML='<p class="cart-empty">Add a dessert before checking out.</p>';return}$('#cart-items').innerHTML='<p class="cart-empty">Checkout is ready to connect to your payment provider.</p>'});$('#sound-toggle').addEventListener('click',()=>{soundOn=!soundOn;$('#sound-toggle').classList.toggle('is-on',soundOn);$('#sound-toggle').setAttribute('aria-pressed',String(soundOn));if(soundOn)beep(660)});function beep(freq=520){if(!soundOn)return;const A=window.AudioContext||window.webkitAudioContext;if(!A)return;const ctx=new A(),o=ctx.createOscillator(),g=ctx.createGain();o.frequency.value=freq;o.type='sine';g.gain.setValueAtTime(.04,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.12);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.12)}addEventListener('keydown',e=>{if(e.key==='Escape'){closeCart();closePanel()}});renderCart();
'''
s = s.replace('\n})();\n</script>', '\n' + extra + '\n})();\n</script>', 1)

p.write_text(s, encoding='utf-8')
print('updated', p, p.stat().st_size)
